<template><main class="content-admin"><header><p>Experiência da marca</p><h1><Icon name="ph:layout-bold"/> Conteúdo da home</h1><span>Textos, campanha, comunidade e roleta são aplicados sem novo deploy.</span></header><section v-if="loading" class="panel">Carregando...</section><form v-else class="panel" @submit.prevent="save"><h2>Campanha inicial</h2><label class="check"><input v-model="draft.campaign.enabled" type="checkbox"> Exibir pop-up ao abrir a home</label><div class="grid"><label>Título<input v-model="draft.campaign.title" maxlength="120"></label><label>Texto do botão<input v-model="draft.campaign.ctaLabel" maxlength="60"></label><label class="wide">Mensagem<textarea v-model="draft.campaign.message" rows="3" maxlength="500"/></label><label>Imagem (URL)<input v-model="draft.campaign.imageUrl" type="url"></label><label>Destino do botão<input v-model="draft.campaign.ctaUrl" type="url"></label></div><h2>Comunidade</h2><div class="grid"><label>Título<input v-model="draft.communityTitle" maxlength="120"></label><label>Mensagem<input v-model="draft.communityMessage" maxlength="300"></label></div><h2>Roleta diária</h2><label class="check"><input v-model="draft.wheel.enabled" type="checkbox"> Ativar roleta</label><div class="grid"><label>Título<input v-model="draft.wheel.title" maxlength="120"></label><label>Link de resgate/suporte<input v-model="draft.wheel.supportUrl" type="url"></label><label class="wide">Mensagem<input v-model="draft.wheel.message" maxlength="300"></label></div><div class="prizes"><article v-for="(prize,index) in draft.wheel.prizes" :key="prize.id"><input v-model="prize.label" aria-label="Nome do prêmio"><input v-model="prize.color" type="color" aria-label="Cor"><input v-model.number="prize.weight" type="number" min="0" aria-label="Peso"><button type="button" aria-label="Remover prêmio" @click="draft.wheel.prizes.splice(index,1)"><Icon name="ph:trash-bold"/></button></article><button type="button" class="ghost" @click="addPrize">Adicionar prêmio</button></div><p v-if="message" :class="type">{{message}}</p><button class="primary" :disabled="saving">{{saving?'Publicando...':'Salvar e publicar'}}</button></form></main></template>
<script setup lang="ts">import type{AppConfig}from'../../../shared/appConfig';import{cloneDefaultAppConfig}from'../../../shared/appConfig';definePageMeta({middleware:'admin',layout:'admin'});const{adminFetch,needsLogin}=useAdmin();const loading=ref(true),saving=ref(false),message=ref(''),type=ref('ok');const draft=reactive<AppConfig['memberExperience']>(cloneDefaultAppConfig().memberExperience);const load=async()=>{loading.value=true;try{const r=await $fetch<{data:AppConfig}>('/api/app-config');Object.assign(draft,JSON.parse(JSON.stringify(r.data.memberExperience)))}finally{loading.value=false}};const addPrize=()=>draft.wheel.prizes.push({id:`prize-${Date.now()}`,label:'Novo prêmio',color:'#8b7cf6',weight:1});const save=async()=>{saving.value=true;try{await adminFetch('/api/app-config',{method:'PUT',body:{memberExperience:draft}});message.value='Conteúdo publicado com sucesso.';type.value='ok'}catch(e:any){message.value=e?.data?.message||'Erro ao publicar.';type.value='error'}finally{saving.value=false}};watch(needsLogin,v=>{if(!v)load()},{immediate:true})</script>
<style scoped>.content-admin{max-width:950px;margin:auto;color:var(--adm-text)}header{margin-bottom:22px}header p{color:var(--adm-accent);font-size:11px;font-weight:900;text-transform:uppercase}h1{display:flex;align-items:center;gap:10px;margin:5px 0}header span{color:var(--adm-muted)}.panel{display:grid;gap:18px;padding:clamp(20px,4vw,32px);border:1px solid var(--adm-border);border-radius:16px;background:var(--adm-panel)}h2{padding-top:10px;border-top:1px solid var(--adm-border);font-size:18px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.wide{grid-column:1/-1}label{display:grid;gap:7px;color:var(--adm-muted);font-size:12px;font-weight:700}input,textarea{padding:11px;border:1px solid var(--adm-border);border-radius:9px;background:var(--adm-input);color:var(--adm-text);font:inherit}.check{display:flex;align-items:center}.check input{width:auto}.prizes{display:grid;gap:8px}.prizes article{display:grid;grid-template-columns:1fr 55px 85px 42px;gap:8px}.prizes article button{border:0;border-radius:8px;background:color-mix(in srgb,var(--adm-red) 12%,transparent);color:var(--adm-red)}.primary,.ghost{padding:12px 17px;border-radius:10px;font-weight:800;cursor:pointer}.primary{justify-self:end;border:0;background:var(--adm-accent);color:#fff}.ghost{border:1px solid var(--adm-border);background:none;color:var(--adm-muted)}.ok{color:var(--adm-green)}.error{color:var(--adm-red)}@media(max-width:620px){.grid{grid-template-columns:1fr}.wide{grid-column:auto}.prizes article{grid-template-columns:1fr 48px 70px 40px}}</style>
